mapper.select:
SELECT * FROM ( select null as disabledThing, erro.REGIST_SEQNO as registSeqno, '01' as maintainStatus, 'A' as statusValid, null as accountName, null as tradeCounterAccNo, null as tradeCounterAccName, null as tradeCounterAccBankName, null as tradeCounterAccBankNo, null as tradeCcy, null as tradeAmt, null as tradeTime, null as postscript, erro.INSTITUTION_CODE as institutionCode, erro.PRD_REGIST_CODE as prdRegistCode, erro.ACCOUNT_NO as accountNo, erro.TRADE_NO as tradeNo, erro.TRADE_PS as tradePs, erro.TRADE_VDATE as tradeVdate, null as remark, erro.ERR_MSG as errMsg from CHB_SALER_STL_DEA_ERRODATA erro where 1=1
and erro.TRADE_PS = #{tradePs,jdbcType=VARCHAR}
and erro.INSTITUTION_CODE = #{institutionCode,jdbcType=VARCHAR}
and erro.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}
and erro.PRD_REGIST_CODE like concat(concat('%',#{prdRegistCode,jdbcType=VARCHAR}),'%')
and erro.TRADE_NO = #{tradeNo,jdbcType=VARCHAR}
and erro.TRADE_VDATE between str_to_date(#{searchTradeVdateStart,jdbcType=VARCHAR},'%Y-%m-%d') and str_to_date(#{searchTradeVdateEnd,jdbcType=VARCHAR},'%Y-%m-%d')
UNION ALL
select '01' as disabledThing, info.REGIST_SEQNO as registSeqno, '02' as maintainStatus, info.DATA_STATUS as statusValid, info.ACCOUNT_NAME as accountName, info.TRADE_COUNTER_ACC_NO as tradeCounterAccNo, info.TRADE_COUNTER_ACC_NAME as tradeCounterAccName, info.TRADE_COUNTER_ACC_BANK_NAME as tradeCounterAccBankName, info.TRADE_COUNTER_ACC_BANK_NO as tradeCounterAccBankNo, info.TRADE_CCY as tradeCcy, info.TRADE_AMT as tradeAmt, info.TRADE_TIME as tradeTime, info.POSTSCRIPT as postscript, info.INSTITUTION_CODE as institutionCode, info.PRD_REGIST_CODE as prdRegistCode, info.ACCOUNT_NO as accountNo, info.TRADE_NO as tradeNo, info.TRADE_PS as tradePs, info.TRADE_VDATE as tradeVdate, info.REMARK as remark, null as errMsg from CHB_SALER_STL_DEAL_INFO info where 1=1
and info.TRADE_PS = #{tradePs,jdbcType=VARCHAR}
and info.INSTITUTION_CODE = #{institutionCode,jdbcType=VARCHAR}
and info.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}
and info.PRD_REGIST_CODE like concat(concat('%',#{prdRegistCode,jdbcType=VARCHAR}),'%')
and info.TRADE_NO = #{tradeNo,jdbcType=VARCHAR}
and info.TRADE_VDATE between str_to_date(#{searchTradeVdateStart,jdbcType=VARCHAR},'%Y-%m-%d') and str_to_date(#{searchTradeVdateEnd,jdbcType=VARCHAR},'%Y-%m-%d')
) as a ORDER BY statusValid DESC
